// Note 17 August 2026: This script is a draft generated by Gemini as a template for how we could
// replace GitHub classroom. I think the overall process here makes sense, which
// is why I'm saving it. When it is time to assign groups, we'll use a process like this one.

import { Octokit } from "@octokit/rest";

// 1. Configuration
const GITHUB_TOKEN = process.env.GITHUB_TOKEN; // Your Personal Access Token
const ORG_NAME = "your-university-org-2026";
const TEMPLATE_REPO = "starter-code-template";

const octokit = new Octokit({ auth: GITHUB_TOKEN });

// 2. Mock Roster (In reality, you'd parse this from a CSV)
const roster = [
  {
    teamName: "team-ada",
    repoName: "project-team-ada",
    members: ["student-github-handle-1", "student-github-handle-2"],
  },
  {
    teamName: "team-turing",
    repoName: "project-team-turing",
    members: ["student-github-handle-3", "student-github-handle-4"],
  }
];

async function provisionClassroom() {
  console.log(`Starting classroom provisioning for ${ORG_NAME}...\n`);

  for (const group of roster) {
    try {
      console.log(`\n--- Processing ${group.teamName} ---`);

      // STEP A: Create the GitHub Team
      console.log(`Creating team: ${group.teamName}`);
      const { data: team } = await octokit.rest.teams.create({
        org: ORG_NAME,
        name: group.teamName,
        privacy: "closed", // Visible to org members, but not public
      });

      // STEP B: Add students to the team
      for (const student of group.members) {
        console.log(`  Adding ${student} to ${group.teamName}`);
        await octokit.rest.teams.addOrUpdateMembershipForUserInOrg({
          org: ORG_NAME,
          team_slug: team.slug,
          username: student,
          role: "member",
        });
      }

      // STEP C: Create a private repo from the template
      console.log(`Creating private repo: ${group.repoName} from template`);
      await octokit.rest.repos.createUsingTemplate({
        template_owner: ORG_NAME,
        template_repo: TEMPLATE_REPO,
        owner: ORG_NAME,
        name: group.repoName,
        private: true,
      });

      // Pause briefly to ensure GitHub backend finishes creating the repo 
      // before we try to assign permissions to it.
      await new Promise(resolve => setTimeout(resolve, 2000));

      // STEP D: Give the team 'push' (write) access to their new repo
      console.log(`Granting ${group.teamName} write access to ${group.repoName}`);
      await octokit.rest.teams.addOrUpdateRepoPermissionsInOrg({
        org: ORG_NAME,
        team_slug: team.slug,
        owner: ORG_NAME,
        repo: group.repoName,
        permission: "push", 
      });

      console.log(`✔ ${group.teamName} provisioned successfully.`);

    } catch (error) {
      console.error(`❌ Error processing ${group.teamName}:`, error.message);
      // In a production script, you'd log this to an error file and continue
    }
  }
  
  console.log("\nProvisioning complete!");
}

provisionClassroom();
